using ModelContextProtocol.Server;
using System.ComponentModel;
using System.Net.Http.Json;
using System.Text.Json.Serialization;

namespace McpServer;

/// <summary>
/// MCP tools that wrap the Open-Meteo weather REST API.
/// The MCP SDK discovers public methods decorated with [McpServerTool]
/// and registers them automatically. Constructor parameters and method
/// parameters are resolved via the DI container.
/// </summary>
[McpServerToolType]
public sealed class WeatherTools
{
    private readonly HttpClient _http;

    // HttpClient is injected by the DI container (see Program.cs).
    public WeatherTools(HttpClient http)
    {
        _http = http;
    }

    [McpServerTool, Description("Get the current temperature for a location.")]
    public async Task<string> GetCurrentWeather(
        [Description("Latitude of the location")] double latitude,
        [Description("Longitude of the location")] double longitude,
        CancellationToken cancellationToken = default)
    {
        var url = $"https://api.open-meteo.com/v1/forecast?latitude={latitude}&longitude={longitude}&current_weather=true";

        var response = await _http.GetFromJsonAsync<WeatherResponse>(url, cancellationToken);

        if (response?.CurrentWeather is null)
            return "Unable to retrieve weather data.";

        var w = response.CurrentWeather;
        return $"Temperature: {w.Temperature}°C, Wind: {w.WindSpeed} km/h, Direction: {w.WindDirection}°";
    }

    [McpServerTool, Description("Get daily high/low forecast for the next 7 days.")]
    public async Task<string> GetWeeklyForecast(
        [Description("Latitude of the location")] double latitude,
        [Description("Longitude of the location")] double longitude,
        CancellationToken cancellationToken = default)
    {
        var url = $"https://api.open-meteo.com/v1/forecast?latitude={latitude}&longitude={longitude}"
                + "&daily=temperature_2m_max,temperature_2m_min&timezone=auto";

        var response = await _http.GetFromJsonAsync<ForecastResponse>(url, cancellationToken);

        if (response?.Daily is null)
            return "Unable to retrieve forecast data.";

        var lines = response.Daily.Time
            .Select((date, i) =>
                $"{date}: High {response.Daily.MaxTemp[i]}°C, Low {response.Daily.MinTemp[i]}°C");

        return string.Join('\n', lines);
    }
}

// --- JSON models for Open-Meteo responses ---

public sealed class WeatherResponse
{
    [JsonPropertyName("current_weather")]
    public CurrentWeather? CurrentWeather { get; set; }
}

public sealed class CurrentWeather
{
    [JsonPropertyName("temperature")]
    public double Temperature { get; set; }

    [JsonPropertyName("windspeed")]
    public double WindSpeed { get; set; }

    [JsonPropertyName("winddirection")]
    public double WindDirection { get; set; }
}

public sealed class ForecastResponse
{
    [JsonPropertyName("daily")]
    public DailyForecast? Daily { get; set; }
}

public sealed class DailyForecast
{
    [JsonPropertyName("time")]
    public List<string> Time { get; set; } = [];

    [JsonPropertyName("temperature_2m_max")]
    public List<double> MaxTemp { get; set; } = [];

    [JsonPropertyName("temperature_2m_min")]
    public List<double> MinTemp { get; set; } = [];
}

